package com.shazwan.idash;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import java.util.*;import java.util.concurrent.*;
/** Repeated real wallpaper/editor operations; preserves preferences and never adds assets. */
public class StabilityChecks extends Instrumentation {
 LauncherActivity a;SharedPreferences prefs;Map<String,?> saved;int count;StringBuilder memory=new StringBuilder();
 final ArrayList<java.lang.ref.WeakReference<Bitmap>> priorWallpapers=new ArrayList<>();
 final ArrayList<java.lang.ref.WeakReference<AppearanceEditor>> priorEditors=new ArrayList<>();
 void check(boolean ok,String text){if(!ok)throw new AssertionError(text);count++;}
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 void ready()throws Exception{CountDownLatch latch=new CountDownLatch(1);a.worker.execute(()->a.main.post(latch::countDown));check(latch.await(45,TimeUnit.SECONDS),"worker drained");waitForIdleSync();}
 void editor()throws Exception{long until=SystemClock.elapsedRealtime()+30000;while((a.appearanceEditor==null||!a.appearanceEditor.cacheReady)&&SystemClock.elapsedRealtime()<until)Thread.sleep(80);check(a.appearanceEditor!=null&&a.appearanceEditor.cacheReady,"editor cache ready");waitForIdleSync();}
 void memory(String at){Debug.MemoryInfo m=new Debug.MemoryInfo();Debug.getMemoryInfo(m);memory.append(at).append(" pss_kib=").append(m.getTotalPss()).append(" java_used_bytes=").append(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory()).append(" native_allocated_bytes=").append(Debug.getNativeHeapAllocatedSize()).append('\n');}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(prefs.getAll());a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();String[] wallpapers=MrIosTheme.wallpapers(a.getAssets());check(wallpapers.length>=2,"existing wallpaper inventory");memory("start");
  for(int cycle=0;cycle<8;cycle++){final int n=cycle;String path="mrios/wallpapers/"+wallpapers[cycle%2==0?0:wallpapers.length-1];priorWallpapers.add(new java.lang.ref.WeakReference<>(a.wallpaperBitmap));ui(()->{if(a.appearanceEditor!=null)a.appearanceEditor.cancel();a.page="home";a.panelVisible=false;a.selectWallpaper(path);});ready();check(path.equals(a.prefs.getString("wallpaper","")),"wallpaper preference "+cycle);check(a.wallpaperBitmap!=null&&!a.wallpaperBitmap.isRecycled(),"wallpaper live "+cycle);check(IosStyle.backdrop(a).frame.bitmap!=null&&!IosStyle.backdrop(a).frame.bitmap.isRecycled(),"frost live "+cycle);
   ui(()->new DashSettings(a).open("Appearance"));editor();AppearanceEditor edit=a.appearanceEditor;GlassAppearance before=GlassAppearance.read(a);ui(()->{edit.change(0,n%3);edit.change(2,n%3);edit.change(3,n%5);});editor();check(edit.cache.frame.quality==cycle%3,"actual quality "+cycle);Bitmap identity=edit.cache.frame.bitmap;ui(()->{edit.change(1,65);edit.change(1,10);edit.change(1,45);});Thread.sleep(100);check(edit.cache.frame.bitmap==identity,"transparency reuses frost "+cycle);
   if(cycle%2==0){ui(edit::apply);check(edit.closed,"Apply releases old editor "+cycle);check(GlassAppearance.read(a).tone==cycle%3,"Apply saves material "+cycle);if(a.appearanceEditor!=null)ui(a.appearanceEditor::cancel);}else{ui(edit::cancel);check(before.same(GlassAppearance.read(a)),"Cancel preserves saved settings "+cycle);}
   check(edit.closed&&edit.cache.frame.bitmap==null,"private preview released "+cycle);priorEditors.add(new java.lang.ref.WeakReference<>(edit));ui(()->{a.controlCenter();check(a.quickControls.observing,"CC resumes "+n);a.quickControls.close();check(!a.quickControls.observing&&!a.quickControls.mediaControl.active&&!a.quickControls.utilitiesControl.active,"CC callbacks released "+n);});memory("cycle_"+cycle);
  }
  ready();Runtime.getRuntime().gc();Thread.sleep(700);memory("after_gc_request");int retainedWalls=0,retainedEditors=0;for(java.lang.ref.WeakReference<Bitmap> ref:priorWallpapers)if(ref.get()!=null)retainedWalls++;for(java.lang.ref.WeakReference<AppearanceEditor> ref:priorEditors)if(ref.get()!=null)retainedEditors++;memory.append("weak_retention_observation wallpapers=").append(retainedWalls).append('/').append(priorWallpapers.size()).append(" editors=").append(retainedEditors).append('/').append(priorEditors.size()).append(" (GC timing and current stack may retain last editor; informational only)\n");check(!a.destroyed,"Activity survived stress");result.putString("stream","PASS: "+count+" wallpaper/appearance stability checks\n"+memory+"PSS observations include TCG/instrumentation; not proof of no long-term leak.\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+count+": "+e+"\n"+memory);}finally{if(a!=null)ui(()->{if(a.appearanceEditor!=null)a.appearanceEditor.close();if(a.quickControls!=null)a.quickControls.close();a.finish();});if(prefs!=null&&saved!=null)AppearanceChecks.restore(prefs,saved);}finish(code,result);}
}
